static int check(TestVector<CBufferChunk>& v, const int* expect, int n)
{
    if ((int)v.size() != n)
        return 0;
    for (int i = 0; i < n; ++i)
        if (KeyOf(v._M_start[i]) != expect[i])
            return 0;
    return 1;
}

