{
    int ok = 1;
    {   // fill-insert with spare capacity, elems_after > n
        TestVector<CBufferChunk> v; v.reserve_exact(16);
        for (int i = 0; i < 5; ++i) v.push(i);
        v._M_fill_insert(v._M_start + 1, 2, MakeElem(9));
        static const int e[] = { 0, 9, 9, 1, 2, 3, 4 };
        ok &= check(v, e, 7); v.clear();
