    {   // spare capacity, elems_after <= n
        TestVector<CBufferChunk> v; v.reserve_exact(16);
        for (int i = 0; i < 3; ++i) v.push(i);
        v._M_fill_insert(v._M_start + 2, 3, MakeElem(7));
        static const int e[] = { 0, 1, 7, 7, 7, 2 };
        ok &= check(v, e, 6); v.clear();
