        v._M_fill_insert(v._M_start, 0, MakeElem(1));
        static const int e[] = { 4 };
        ok &= check(v, e, 1); v.clear();
    }

    if (!ok) { std::printf("009c75a0_TEST FAIL\n"); return 1; }
    std::printf("009c75a0_TEST PASS\n");
    return 0;
}

