                dst += rect.Pitch;
                src += box.RowPitch;
            }
            src = sliceStart + box.SlicePitch;
            textures[z].Swizzle(rect);
            textures[z].Unlock();
        }
        ++g_swizzles;
    }
};

int main()
{
    CMockVolume v;
    v.Width = 3; v.Height = 5; v.Depth = 4; v.Bpp = 4;
