    {   // single insert in the middle (fill_len == 1, copy the remainder)
        TestVector<SHelperEntry> v; v.reserve_exact(3);
        for (int i = 0; i < 3; ++i) v.push(i);
        v._M_insert_overflow(v._M_start + 1, MakeElem(8), 1, false);
        static const int e[] = { 0, 8, 1, 2 };
        ok &= check(v, e, 4);
        ok &= v._M_end_of_storage - v._M_start == 6;
        v.clear();
    }
    {   // fill_len > old size: len = old + fill_len
        TestVector<SHelperEntry> v; v.reserve_exact(2);
        for (int i = 0; i < 2; ++i) v.push(i);
        v._M_insert_overflow(v._M_start + 2, MakeElem(6), 3, false);
        static const int e[] = { 0, 1, 6, 6, 6 };
        ok &= check(v, e, 5);
        ok &= v._M_end_of_storage - v._M_start == 5;
        v.clear();
